describe("exp-003 conditions", () => {
  const tasks = [
    { taskId: "t1", taskClass: "bug_fix", title: "a", description: "d", fixturePath: "x" },
    { taskId: "t2", taskClass: "refactor", title: "b", description: "d", fixturePath: "y" }
