    expect(new Set(runs.map((run) => run.condition)).size).toBe(3)
  })

  it("computes bootstrap ms from categories", () => {
    expect(
      environmentBootstrapMs({
        package_manager: 100,
        git: 50,
        agent_internal: 0,
        build: 0,
        file_read: 0,
        file_write: 0,
        repository_discovery: 0,
        search: 0,
        shell_other: 0,
        test: 0,
        typecheck: 0,
        unknown: 0
      })
    ).toBe(150)
  })
})

